    SELECT ReservationCode, SpaceCode, StartDateTime, EndDateTime, BookingStatus, DataOrigin
    INTO [stg].[Reservation_HourAlignmentBackup]
    FROM [stg].[Reservation];
    DELETE FROM [bi].[FactReservationHour];
